pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 blockNum, uint256 timestamp, uint128 amount) public {
        vm.assume(amount == 10 ether);
        vm.assume(timestamp > 0);
        vm.assume(blockNum > 0);
        vm.deal(address(this), amount);
        vm.roll(blockNum);
        vm.warp(timestamp);
        // prime pastBlockTime to be strictly less than timestamp
        vm.roll(blockNum + 1);
        vm.warp(timestamp - 1);
        (bool ok1,) = address(c).call{value: amount}("");
        require(ok1, "setup call failed");
        // now the main call with timestamp strictly greater
        vm.roll(blockNum);
        vm.warp(timestamp);
        (bool ok2,) = address(c).call{value: amount}("");
        require(ok2, "main call failed");
        bool mutantTransfer = (blockNum % 14 == 0);
        bool refTransfer = (blockNum % 15 == 0);
        if (mutantTransfer && !refTransfer) {
            assertTrue(address(c).balance == 0);
        } else {
            assertTrue(true);
        }
    }
}

