pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 blockNum, uint256 timestampGap, uint128 value) public {
        // Keep the block number in a reasonable range so the fuzzer can hit conditions quickly.
        bound(blockNum, 1, 1_000_000);
        // A strictly positive gap ensures block.timestamp > pastBlockTime on every call.
        bound(timestampGap, 1, 1_000_000);
        // Restrict value to the exact required contribution of 10 ether.
        vm.assume(value == 10 ether);

        // Actor with enough ether to repeatedly contribute 10 ether.
        address actor = makeAddr("actor");
        vm.deal(actor, 100 ether);

        // Warp and roll to a neutral starting state.
        vm.warp(0);
        vm.roll(0);

        // First contribution — must succeed.
        vm.prank(actor);
        (bool ok,) = address(c).call{value: value}("");
        require(ok, "first contribution failed");

        // Warp forward by the random gap and set the fuzzed block number.
        vm.warp(block.timestamp + timestampGap);
        vm.roll(blockNum);

        // Second contribution under the fuzzed block number.
        vm.prank(actor);
        (ok,) = address(c).call{value: value}("");
        require(ok, "second contribution failed");

        // After the second call the balance must be zero if and only if the block
        // was divisible by 15 (the condition in the reference C).
        bool balanceIsZero = address(c).balance == 0;
        bool blockDivisibleBy15 = (blockNum % 15) == 0;
        assertTrue(balanceIsZero == blockDivisibleBy15);
    }
}

