pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public {
        c = new C();
    }

    function testFuzz_property(uint256 blockNum, uint128 callValue, uint128 startBalance) public {
        // Keep block number in a reasonable range and ensure it's not zero for timestamp logic
        blockNum = bound(blockNum, 1, 1e8);
        // Set the exact call value to 10 ether
        uint256 exactVal = 10 ether;

        // Ensure the contract has some initial balance that can be transferred out
        // (the fallback contribution itself provides the balance, but we also need to make sure
        //  the initial balance does not interfere with the transfer logic).
        // We use startBalance as an existing balance before the call.
        startBalance = uint128(bound(uint256(startBalance), 0, type(uint128).max));

        // Set block number and advance time to satisfy timestamp requirement
        vm.roll(blockNum);
        // pastBlockTime is initially 0, so any timestamp > 0 is fine when pastBlockTime = 0,
        // but if we want to allow multiple calls we'd need to handle pastBlockTime.
        // For this single-call property, we just need a timestamp > 0 and > pastBlockTime.
        // Since setUp deploys c and pastBlockTime = 0, a timestamp of 1 works for the first call.
        // The fuzzer can provide blockNum, and we just warp to blockNum to make it consistent.
        vm.warp(blockNum);

        // Give the contract an initial balance to observe the full transfer effect
        vm.deal(address(c), startBalance);

        // Fund an arbitrary sender and make the fallback call
        address sender = makeAddr("sender");
        vm.deal(sender, exactVal);
        vm.prank(sender);
        (bool success, ) = address(c).call{value: exactVal}("");

        // The call should succeed (10 ether sent, timestamp condition met)
        require(success, "fallback call failed");

        // The property: after a valid call, c.balance == 0 iff block.number % 15 == 0
        bool divBy15 = (blockNum % 15 == 0);
        bool balanceIsZero = (address(c).balance == 0);

        assertTrue(balanceIsZero == divBy15);
    }
}

