import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 timestamp) public {
        vm.assume(timestamp > 0);
        address actor = address(0x1234);
        vm.deal(actor, 100 ether);

        // First call with timestamp T1
        vm.warp(timestamp);
        vm.prank(actor);
        (bool ok1, ) = address(c).call{value: 10 ether}("");
        require(ok1, "call1 failed");
        uint256 past1 = c.pastBlockTime();

        // Second call with same timestamp T1 (violates require(block.timestamp > pastBlockTime) in reference)
        vm.warp(timestamp);
        vm.prank(actor);
        (bool ok2, ) = address(c).call{value: 10 ether}("");

        if (ok2) {
            uint256 past2 = c.pastBlockTime();
            // If second call succeeds, pastBlockTime must be strictly greater than previous
            assertTrue(past2 > past1);
        } else {
            // Second call reverts, property holds vacuously
            assertTrue(true);
        }
    }
}

