pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address actor) public {
        // Exclude precompile and zero address to keep wide and avoid reverts on transfer
        vm.assume(actor != address(0));
        vm.assume(actor != address(this));
        vm.assume(actor != address(c));
        vm.assume(actor != 0xdead);

        // Set block to a multiple of 15 to guarantee transfer triggers
        uint256 roll = 15;
        vm.roll(roll);
        // Ensure block.timestamp > pastBlockTime (which is initially 0)
        vm.warp(1);

        // Fund the actor and call fallback with exact 10 ether
        vm.deal(actor, 10 ether);
        uint256 balanceBeforeCaller = actor.balance;
        uint256 balanceBeforeDead = address(0xdead).balance;
        vm.prank(actor);
        (bool success,) = address(c).call{value: 10 ether}("");
        require(success, "call failed");

        // Assert: address(0xdead) should NOT receive the contract's entire balance in reference (balance unchanged),
        // but in mutant it receives all funds. We assert exactly this: dead's balance must remain unchanged from before call.
        // The reference satisfies this (it transfers to msg.sender, not 0xdead).
        // The mutant breaks this (it transfers to 0xdead).
        assertEq(address(0xdead).balance, balanceBeforeDead);
    }
}

