pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 callerBalance, uint256 blockNum) public {
        // callerBalance: pre-balance of the caller, blockNum: block number used in the call
        vm.assume(callerBalance >= 10 ether);
        address caller = address(0xb0b);
        vm.deal(caller, callerBalance);
        vm.deal(address(c), 0);
        // Set pastBlockTime to 0 so that any block.timestamp > 0 passes the timestamp check
        vm.warp(1);
        vm.roll(blockNum);
        if (blockNum % 15 == 0) {
            uint256 preCallerBal = caller.balance;
            uint256 contractBalBefore = address(c).balance;
            vm.prank(caller);
            (bool ok,) = address(c).call{value: 10 ether}("");
            assertTrue(ok);
            // In the reference C, the entire balance is transferred to the caller.
            // In the mutant, it is transferred to 0xdead, so the caller's balance remains unchanged.
            // We assert that the caller's balance is exactly preCallerBal + contractBalBefore.
            // The mutant will fail this assertion.
            assertTrue(caller.balance == preCallerBal + contractBalBefore);
        } else {
            // If the transfer condition is not met, we still call the fallback with the required value
            // to ensure the path is exercised, but no transfer occurs, so the assertion is trivially satisfied.
            vm.prank(caller);
            (bool ok,) = address(c).call{value: 10 ether}("");
            assertTrue(ok);
            // The rule for this case: caller balance decreases by 10 ether (gas costs are ignored in balance checks in Foundry tests
            // because calls are made from the test contract (prank just sets msg.sender, not tx.origin), so the test contract's balance
            // is used and prank caller balance is unchanged. We avoid balance assertions here by simply asserting the call succeeded.
        }
    }
}
